MESSAGES.update({
    "filename_policy.dos83.tooltip": {"en": "Restrict newly entered and generated disk/image filenames to an eight-character name and three-character extension. Enabling this turns off track-number/title naming for MIDI conversions.", "es": "Restringe los nombres nuevos y generados en discos e imágenes a ocho caracteres y una extensión de tres. Al activarlo se desactiva el nombre por número de pista y título en las conversiones MIDI.", "fr": "Limite les noms nouveaux et générés sur les disques et images à huit caractères et une extension de trois. L'activation désactive les noms MIDI par numéro de piste et titre.", "de": "Beschränkt neue und erzeugte Datei-/Image-Namen auf acht Zeichen und eine dreistellige Erweiterung. Beim Aktivieren wird die Benennung nach Titelnummer und Titel für MIDI-Konvertierungen ausgeschaltet.", "it": "Limita i nomi nuovi e generati su dischi e immagini a otto caratteri e un'estensione di tre. L'attivazione disabilita i nomi MIDI basati su numero traccia e titolo.", "pt-BR": "Restringe nomes novos e gerados em discos e imagens a oito caracteres e uma extensão de três. Ativar esta opção desativa nomes por número da faixa e título nas conversões MIDI.", "bg": "Ограничава новите и генерираните имена в дискове и образи до осем знака и разширение от три. Включването изключва именуването по номер на песен и заглавие при MIDI преобразуване.", "nl": "Beperkt nieuwe en gegenereerde namen op schijven en images tot acht tekens en een extensie van drie. Inschakelen zet MIDI-namen op basis van tracknummer en titel uit.", "pl": "Ogranicza nowe i generowane nazwy na dyskach i obrazach do ośmiu znaków oraz trzyznakowego rozszerzenia. Włączenie wyłącza nazwy MIDI według numeru ścieżki i tytułu.", "ja": "新しく入力または生成するディスク／イメージ内のファイル名を、8 文字の名前と 3 文字の拡張子に制限します。有効にすると、MIDI 変換時のトラック番号／曲名による命名はオフになります。", "ko": "새로 입력하거나 생성하는 디스크/이미지 파일 이름을 8자 이름과 3자 확장자로 제한합니다. 켜면 MIDI 변환의 트랙 번호/곡 제목 이름 지정이 꺼집니다.", "zh-Hans": "将新输入和生成的磁盘/映像文件名限制为八字符名称和三字符扩展名。启用后会关闭 MIDI 转换的曲目编号/标题命名。"},
    "filename_policy.long_conversion.tooltip": {"en": "Example: 01 - Moon River.mid. In floppy/image mode, the Filename column previews the descriptive name. Choosing this turns off Use 8.3 filenames.", "es": "Ejemplo: 01 - Moon River.mid. En modo disquete/imagen, la columna Nombre muestra una vista previa del nombre descriptivo. Elegirlo desactiva Usar nombres 8.3.", "fr": "Exemple : 01 - Moon River.mid. En mode disquette/image, la colonne Nom affiche un aperçu du nom descriptif. Ce choix désactive Utiliser les noms 8.3.", "de": "Beispiel: 01 - Moon River.mid. Im Disketten-/Image-Modus zeigt die Dateinamenspalte den beschreibenden Namen. Diese Auswahl schaltet 8.3-Dateinamen verwenden aus.", "it": "Esempio: 01 - Moon River.mid. In modalità floppy/immagine, la colonna Nome mostra l'anteprima del nome descrittivo. Questa scelta disattiva Usa nomi 8.3.", "pt-BR": "Exemplo: 01 - Moon River.mid. No modo disquete/imagem, a coluna Nome mostra o nome descritivo. Esta escolha desativa Usar nomes 8.3.", "bg": "Пример: 01 - Moon River.mid. В режим на флопи/образ колоната за име показва описателното име. Този избор изключва Използване на 8.3 имена.", "nl": "Voorbeeld: 01 - Moon River.mid. In diskette-/imagemodus toont de kolom Bestandsnaam de beschrijvende naam. Deze keuze schakelt 8.3-bestandsnamen gebruiken uit.", "pl": "Przykład: 01 - Moon River.mid. W trybie dyskietki/obrazu kolumna Nazwa pokazuje opisową nazwę. Ten wybór wyłącza opcję Używaj nazw 8.3.", "ja": "例: 01 - Moon River.mid。フロッピー／イメージモードでは、ファイル名列に説明的な名前が表示されます。これを選ぶと「8.3 ファイル名を使用」はオフになります。", "ko": "예: 01 - Moon River.mid. 플로피/이미지 모드에서는 파일 이름 열에 설명형 이름이 미리 표시됩니다. 이 옵션을 선택하면 8.3 파일 이름 사용이 꺼집니다.", "zh-Hans": "示例：01 - Moon River.mid。在软盘/映像模式下，文件名列会预览描述性名称。选择此项会关闭“使用 8.3 文件名”。"},
    "filename_policy.long_read_floppy.tooltip": {"en": "Use names such as 01 - Moon River.mid for existing and converted MIDI songs saved to a folder. The Filename column previews those names. Unavailable while Use 8.3 filenames is enabled.", "es": "Usa nombres como 01 - Moon River.mid para las canciones MIDI existentes y convertidas guardadas en una carpeta. La columna Nombre muestra una vista previa. No disponible mientras Usar nombres 8.3 esté activado.", "fr": "Utilise des noms tels que 01 - Moon River.mid pour les morceaux MIDI existants et convertis enregistrés dans un dossier. La colonne Nom les prévisualise. Indisponible lorsque Utiliser les noms 8.3 est activé.", "de": "Verwendet Namen wie 01 - Moon River.mid für vorhandene und konvertierte MIDI-Titel, die in einem Ordner gespeichert werden. Die Dateinamenspalte zeigt diese Namen. Nicht verfügbar, wenn 8.3-Dateinamen verwenden aktiviert ist.", "it": "Usa nomi come 01 - Moon River.mid per i brani MIDI esistenti e convertiti salvati in una cartella. La colonna Nome ne mostra l’anteprima. Non disponibile quando Usa nomi 8.3 è attivo.", "pt-BR": "Usa nomes como 01 - Moon River.mid para músicas MIDI existentes e convertidas salvas em uma pasta. A coluna Nome mostra esses nomes. Indisponível enquanto Usar nomes 8.3 estiver ativado.", "bg": "Използва имена като 01 - Moon River.mid за съществуващи и преобразувани MIDI песни, записани в папка. Колоната за име ги показва предварително. Не е налично, когато Използване на 8.3 имена е включено.", "nl": "Gebruikt namen zoals 01 - Moon River.mid voor bestaande en geconverteerde MIDI-nummers die in een map worden opgeslagen. De kolom Bestandsnaam toont ze vooraf. Niet beschikbaar wanneer 8.3-bestandsnamen gebruiken is ingeschakeld.", "pl": "Używa nazw takich jak 01 - Moon River.mid dla istniejących i przekonwertowanych utworów MIDI zapisywanych do folderu. Kolumna Nazwa pokazuje ich podgląd. Niedostępne, gdy opcja Używaj nazw 8.3 jest włączona.", "ja": "既存および変換後のMIDI曲をフォルダーに保存するとき、01 - Moon River.mid のような名前を使います。ファイル名列にその名前が表示されます。「8.3 ファイル名を使用」が有効な間は利用できません。", "ko": "기존 및 변환된 MIDI 곡을 폴더에 저장할 때 01 - Moon River.mid 같은 이름을 사용합니다. 파일 이름 열에 해당 이름이 미리 표시됩니다. 8.3 파일 이름 사용이 켜져 있으면 사용할 수 없습니다.", "zh-Hans": "将现有和转换后的 MIDI 乐曲保存到文件夹时，使用 01 - Moon River.mid 之类的名称。文件名列会预览这些名称。启用“使用 8.3 文件名”时不可用。"},
})


